/**
 * @brief 根据注入的 G-code 文本同步更新 MC 状态与调试事件
 * @param gcode G-code 零结尾字符串
 * @param seq 16位序列号
 */
static void mc_apply_gcode_side_effects(const char *gcode, uint16_t seq)
{
    if (gcode == NULL)
    {
        return;
    }
    s_dbg_state.ack_seq = seq;
    if (strncmp(gcode, "G28", 3U) == 0)
    {
        current_position[X_AXIS] = 0.0f;
        current_position[Y_AXIS] = 0.0f;
        current_position[Z_AXIS] = 0.0f;
        axis_known_position[X_AXIS] = true;
        axis_known_position[Y_AXIS] = true;
        axis_known_position[Z_AXIS] = true;
        mc_debug_notify_motion("HOME", 0x07U, 1500U);
    }
    else if ((gcode[0] == 'T') && (gcode[1] >= '0') && (gcode[1] <= '3'))
    {
        const uint8_t slot = (uint8_t)(gcode[1] - '0');
        active_extruder = slot;
        mc_debug_notify_filament("SELECT", slot, s_dbg_state.filament_mask, "DONE");
    }
}

